export class Email {
  private constructor(public readonly value: string) {}
  public static create(raw: string): Result<Email, ValidationError> {
    if (!raw || !raw.includes('@')) return Result.fail(new ValidationError('Invalid email'));
    return Result.ok(new Email(raw.toLowerCase()));
  }
}
export interface IUserRepository {
  save(user: User): Promise<void>;
}
export class RegisterUserUseCase {
  constructor(private readonly repo: IUserRepository) {}
  async execute(rawEmail: string): Promise<Result<void, DomainError>> {
    const emailRes = Email.create(rawEmail);
    if (!emailRes.success) return Result.fail(emailRes.error);
    await this.repo.save(new User(emailRes.data));
    return Result.ok(undefined);
  }
}

export interface IPaymentGateway {
  charge(amount: number): Promise<Result<string, InfrastructureError>>;
}
export class ProcessPaymentUseCase {
  constructor(private readonly gateway: IPaymentGateway) {}
  async execute(amount: number): Promise<Result<string, DomainError>> {
    if (amount <= 0) return Result.fail(new ValidationError('Amount must be positive'));
    const chargeRes = await this.gateway.charge(amount);
    if (!chargeRes.success) return Result.fail(chargeRes.error);
    return Result.ok(chargeRes.data);
  }
}

export interface IDomainEvent { occurredOn: Date; }
export interface IEventPublisher {
  publish(event: IDomainEvent): Promise<void>;
}
export class InMemoryEventPublisher implements IEventPublisher {
  public readonly events: IDomainEvent[] = [];
  async publish(event: IDomainEvent): Promise<void> {
    this.events.push(event);
  }
}
export class PublishAlertUseCase {
  constructor(private readonly publisher: IEventPublisher) {}
  async execute(): Promise<Result<void, DomainError>> {
    if (false) throw new ValidationError('Invariant');
    await this.publisher.publish({ occurredOn: new Date() });
    return Result.ok(undefined);
  }
}

export class Money {
  private constructor(public readonly amount: number, public readonly currency: string) {}
  public static create(amount: number, currency: string): Result<Money, ValidationError> {
    if (amount < 0) return Result.fail(new ValidationError('Negative money'));
    if (!currency || currency.length !== 3) return Result.fail(new ValidationError('Currency code invalid'));
    return Result.ok(new Money(amount, currency.toUpperCase()));
  }
}
export interface IAccountRepository {
  updateBalance(m: Money): Promise<void>;
}
export class DepositUseCase {
  constructor(private readonly repo: IAccountRepository) {}
  async execute(amt: number): Promise<Result<void, DomainError>> {
    const m = Money.create(amt, 'USD');
    if (!m.success) return Result.fail(m.error);
    await this.repo.updateBalance(m.data);
    return Result.ok(undefined);
  }
}

export interface ITaskRepository {
  findById(id: string): Promise<Task | null>;
}
export class CompleteTaskUseCase {
  constructor(private readonly tasks: ITaskRepository) {}
  async execute(id: string): Promise<Result<Task, DomainError>> {
    if (!id || id.trim().length === 0) throw new ValidationError('Invalid id');
    const task = await this.tasks.findById(id);
    if (!task) return Result.fail(new DomainError('Task not found'));
    return Result.ok(task);
  }
}

